urlset:
  https://yusuke8696.github.io/
{%- assign documents = site.static_files | concat: site.pages | sort: 'path' -%}
{%- for document in documents -%}
  {%- assign document_path = document.path -%}
  {%- assign first_character = document_path | slice: 0, 1 -%}
  {%- if first_character == '/' -%}
    {%- assign document_path = document_path | remove_first: '/' -%}
  {%- endif -%}
  {%- assign prefix = document_path | slice: 0, 9 -%}
  {%- assign extension = document_path | split: '.' | last -%}
  {%- if prefix == 'articles/' and extension == 'html' %}
  {{ document_path | prepend: 'https://yusuke8696.github.io/' | xml_escape }}
  {%- endif -%}
{%- endfor %}
